const fs = require('fs');
const path = require('path');
const Q = [];
const CREATED_BY = 1;
function add(sub, stem, options, correct, rule, fail, lang = 'English') {
  if (!Array.isArray(options) || options.length !== 4) throw new Error(`four options required: ${stem}`);
  if (correct < 0 || correct > 3) throw new Error(`bad key: ${stem}`);
  const answer = options[correct];
  const explanation = `${rule} Therefore, the correct option is "${answer}." The other choices fail because ${fail}.`;
  Q.push({ sub, lang, stem, options, correct, explanation });
}
// Constitution: original application items grounded in the 1987 Constitution.
add(1,'Which constitutional principle requires government authority to remain answerable to the people?', ['Public accountability','Private ownership of agencies','Hereditary succession','Military supremacy'],0,'Public accountability makes officials answerable for the exercise of public power','the other choices replace democratic accountability with private, hereditary, or military control');
add(1,'A law must respect the separation of powers. Which branch primarily makes statutes?', ['The legislative branch','The executive branch','The judicial branch','Local school boards'],0,'Congress, the legislative branch, exercises legislative power under Article VI','the executive and judicial branches implement or interpret law, while school boards are not a national branch');
add(1,'Which institution tries impeachment cases under the 1987 Constitution?', ['The Senate','The House of Representatives','The Commission on Audit','The Supreme Court as a trial jury'],0,'The Senate has the sole power to try and decide impeachment cases after the House initiates them','the House initiates, while COA and the Supreme Court do not act as the impeachment trial body');
add(1,'The President is the commander-in-chief of which constitutional institution?', ['The armed forces of the Philippines','All private corporations','Every foreign military','The independent constitutional commissions'],0,'Article VII makes the President commander-in-chief of the armed forces','the other choices are outside that constitutional command relationship');
add(1,'Which right is most directly involved when government prevents a peaceful newspaper from criticizing a policy?', ['Freedom of the press','Right to travel only','Right against double jeopardy','Right to form a family'],0,'Freedom of the press protects publication and criticism subject to lawful limits','the other rights do not directly concern publication of criticism');
add(1,'A search of a home generally requires a judicial warrant based on probable cause. This rule protects the:', ['Right against unreasonable searches and seizures','Right to information on public matters','Right to suffrage','Right to just compensation'],0,'The Bill of Rights protects persons and homes from unreasonable searches and seizures','the alternatives concern information, voting, or property compensation rather than search procedure');
add(1,'Which body audits government funds and property?', ['Commission on Audit','Commission on Elections','Civil Service Commission','Department of Trade and Industry'],0,'The Constitution assigns government auditing to the Commission on Audit','the other bodies have election, civil-service, or trade functions');
add(1,'What is the constitutional term for citizenship acquired from birth without needing an act to acquire or perfect it?', ['Natural-born citizenship','Temporary residency','Naturalized status only','Tourist status'],0,'Natural-born citizens are citizens from birth without needing an act to acquire or perfect citizenship','residency, naturalization, and tourism describe different legal statuses');
add(1,'Which constitutional commission administers the civil service?', ['Civil Service Commission','Commission on Audit','Commission on Elections','Commission on Human Rights'],0,'The Civil Service Commission administers the government personnel system','COA audits, COMELEC administers elections, and CHR investigates human-rights concerns');
add(1,'The constitutional guarantee that no person may be deprived of life, liberty, or property without due process is a protection against:', ['Arbitrary government action','All private disagreements','Every tax obligation','Routine filing errors'],0,'Due process requires fair legal procedures and a lawful basis before deprivation','the alternatives are not the constitutional mischief targeted by due process');
add(1,'Which statement best describes the constitutional role of the judiciary?', ['It settles actual controversies involving enforceable rights','It writes the annual national budget alone','It appoints every local official','It conducts all elections'],0,'The judiciary resolves actual controversies and may review grave abuse or constitutional conflicts','budgeting, local appointments, and election administration belong primarily to other institutions');
add(1,'Under the Constitution, the privilege of the writ of habeas corpus relates most closely to:', ['Protection against unlawful detention','Ownership of a registered vehicle','Approval of a business name','Assessment of real property tax'],0,'Habeas corpus tests unlawful restraint of personal liberty','the alternatives concern property, business registration, or taxation');
add(1,'Which statement reflects the constitutional policy on civilian authority?', ['Civilian authority is supreme over the military','Military officers may replace elected institutions whenever they wish','Courts are subordinate to private groups','Local officials command the national armed forces'],0,'The Constitution places civilian authority above the military in a democratic republic','the other choices reverse or invent the constitutional chain of authority');
add(1,'A valid classification for equal-protection purposes should be related to the law purpose and apply to:', ['All members of the same class','Only the official who drafted it','Foreign visitors only','One named person only'],0,'Equal protection requires a reasonable classification that applies alike to all in the same class','the other choices are arbitrary limits and do not describe equal treatment');
add(1,'Which governmental power is exercised when the state takes private property for public use with payment?', ['Eminent domain','Police patrol only','Judicial notice','Legislative privilege'],0,'Eminent domain is the taking of private property for public use with just compensation','the alternatives do not describe a compensated public-use taking');
add(1,'A bill becomes a law over the President\'s veto when:', ['Two-thirds of all the members of each House vote to pass it again','A single senator announces approval','A local mayor signs it','The Supreme Court writes a replacement bill'],0,'The Constitution permits Congress to override a veto by a two-thirds vote of all members of each House','the other actions do not satisfy the constitutional override requirement');
add(1,'Which is a constitutional qualification for a Philippine senator?', ['At least 35 years old on election day','At least 18 years old on election day','A licensed lawyer in every case','A former governor in every case'],0,'The Constitution requires a senator to be at least 35 years old on election day','the other choices are not universal constitutional qualifications');
add(1,'Which right allows qualified citizens to participate directly in choosing public officials?', ['Suffrage','Habeas data','Freedom from impairment of contracts','Right to bail only'],0,'Suffrage is the constitutional right to vote subject to legal qualifications','the alternatives concern information, contracts, or criminal procedure');
add(1,'The constitutional ban on ex post facto laws means government may not:', ['Punish an act that was not criminal when done','Collect a lawful tax','Require a public permit','Publish a statute'],0,'An ex post facto law retroactively makes conduct criminal or increases its punishment','the other choices are not retroactive criminal punishment');
add(1,'Which constitutional office is designed to investigate and prosecute illegal acts of public officials?', ['The Office of the Ombudsman','The Philippine Sports Commission','The National Library','The Weather Bureau'],0,'The Ombudsman investigates and prosecutes alleged illegal acts or omissions of public officials as provided by law','the other offices do not have that constitutional accountability function');
add(1,'Local autonomy means local government units may:', ['Manage local affairs within the Constitution and national law','Ignore every national statute','Declare war independently','Print national currency'],0,'Local autonomy allows self-government within constitutional and statutory limits','the alternatives claim powers reserved to the national government or prohibited by law');
add(1,'Which constitutional commission conducts elections and enforces election laws?', ['Commission on Elections','Commission on Audit','Civil Service Commission','Department of Finance'],0,'COMELEC administers and enforces election laws','the other bodies audit, manage civil service, or handle fiscal administration');
add(1,'The constitutional right to information generally concerns:', ['Matters of public concern subject to lawful limitations','Private passwords of every citizen','All confidential medical records','Every sealed court exhibit without exception'],0,'The right to information covers matters of public concern subject to constitutional and statutory limits','the other choices ignore privacy, privilege, or other lawful restrictions');
add(1,'Which statement about a person accused of a crime is constitutionally sound?', ['The accused is presumed innocent until the contrary is proved','The accused must prove innocence before trial','A rumor is conclusive proof','A confession is required in every case'],0,'Presumption of innocence places the burden of proof on the prosecution','the other choices reverse the burden or treat unreliable material as conclusive');
add(1,'A constitutional limitation on public funds is that money may be paid out only:', ['Pursuant to an appropriation made by law','When a private donor requests it','Whenever an employee asks orally','Without any accounting record'],0,'Public funds require legal appropriation and proper public accountability','the other choices bypass the legal and accounting safeguards');
// RA 6713: facts checked against the statute and CSC SALN guidance.
add(2,'Under RA 6713, which interest must public officials place above personal interest?', ['Public interest','A supplier\'s interest','A relative\'s business interest','A personal investment target'],0,'Section 4 requires public interest to be upheld over personal interest','the other choices are private interests that the norm is meant to subordinate');
add(2,'A public employee receives a valuable gift from a bidder whose transaction the employee handles. The safer statutory conclusion is that the gift is:', ['A prohibited gift connected with official duties','Automatically harmless because it is wrapped','Required by professionalism','A personal salary increase'],0,'Section 7 prohibits soliciting or accepting gifts connected with official duties or regulated transactions','packaging, professionalism, and salary labels do not remove the conflict');
add(2,'RA 6713 generally requires a public official to respond to a public letter within:', ['Fifteen working days','One calendar hour','One decade','Only after an election'],0,'Section 5 calls for a response within fifteen working days and states the action taken','the other time periods do not match the statutory duty');
add(2,'The annual deadline stated in RA 6713 for filing the SALN is:', ['On or before April 30','December 31 only','The employee\'s birthday','Whenever an audit begins'],0,'Section 8 states that the annual SALN is filed on or before April 30','the other dates are not the statutory annual deadline');
add(2,'A SALN is generally filed after assumption of office within:', ['Thirty days','Three years','One working hour','Only after promotion'],0,'Section 8 requires filing within thirty days after assumption of office','the other choices do not state the statutory period');
add(2,'When a public officer separates from service, the SALN is generally due within:', ['Thirty days after separation','Ten years after separation','Only if asked by a neighbor','Before the officer\'s first appointment'],0,'Section 8 requires a filing within thirty days after separation from service','the alternatives use an incorrect trigger or no legal duty');
add(2,'Political neutrality under RA 6713 means a public employee should:', ['Serve people without unfair discrimination based on party affiliation','Refuse service to political opponents','Campaign during every transaction','Serve only campaign donors'],0,'Political neutrality requires service without unfair discrimination based on party affiliation or preference','the other choices are partisan discrimination');
add(2,'The norm of simple living asks officials and their families to:', ['Lead modest lives appropriate to position and income','Display wealth to prove competence','Hide every lawful asset','Reject all lawful compensation'],0,'Simple living means modest conduct appropriate to position and lawful income','the alternatives promote extravagance, concealment, or an unrelated refusal of compensation');
add(2,'Which act best illustrates professionalism under RA 6713?', ['Discharging duties with excellence, skill, and dedication','Selling preferential access to a file','Delaying every request without reason','Using public equipment for private profit'],0,'Professionalism calls for excellence, intelligence, skill, devotion, and dedication to duty','the other choices are patronage, neglect, or misuse');
add(2,'A conflict of interest exists when an official\'s private business interest may be:', ['Opposed to or affected by faithful performance of official duty','Completely unrelated to any official action','A hobby with no financial connection','A public holiday'],0,'RA 6713 defines conflict of interest around a private interest opposed to or affected by official duty','the other choices do not create the required official-private connection');
add(2,'Divestment under RA 6713 means:', ['Voluntarily and completely disposing of a conflicting interest','Moving an asset to another desk','Listing an asset without changing ownership','Borrowing a colleague\'s ID'],0,'Divestment transfers title or disposes of the conflicting interest so the official no longer holds it','the alternatives do not remove ownership or control');
add(2,'A public employee using confidential procurement data to help a friend violates the rule against:', ['Disclosure or misuse of confidential information','Simple living only','Annual leave scheduling','Public speaking'],0,'Section 7 bars using or divulging confidential information to advance private interests or prejudice public interest','the other choices do not describe misuse of nonpublic official information');
add(2,'Which duty supports openness in government service?', ['Making public documents accessible during reasonable working hours','Destroying all records immediately','Giving documents only to relatives','Refusing to explain procedures'],0,'RA 6713 directs offices to make public documents accessible and information understandable','the other choices defeat transparency and public access');
add(2,'For official papers, RA 6713 says they should contain, as far as practicable, no more than:', ['Three signatories','Thirty signatories','One hundred signatories','No identifying signatory'],0,'Section 5 limits official papers to not more than three signatories when practicable','the other choices ignore the anti-red-tape requirement');
add(2,'Which agency has primary responsibility for administration and enforcement of RA 6713?', ['Civil Service Commission','Department of Tourism','National Archives alone','A private contractor'],0,'Section 12 assigns primary administration and enforcement to the Civil Service Commission','the other choices are not the agency named by the statute');
add(2,'A public officer recommending a person to a private enterprise with a regular pending transaction with the officer\'s office is:', ['A prohibited outside-employment-related act','Always required by courtesy','A SALN filing date','A constitutional amendment'],0,'Section 7 prohibits that recommendation during incumbency','the other choices misclassify the conduct and do not address the conflict');
add(2,'Which statement about public service and relatives is consistent with RA 6713?', ['Officials must avoid undue favors to relatives because of office','Officials must award every contract to relatives','Relatives are exempt from all ethical rules','Family preference is always public interest'],0,'The norm of justness and sincerity bars undue favors to relatives on account of office, subject to the statutory qualification','the other choices turn public power into automatic family patronage');
add(2,'The public\'s right to know under the SALN provisions relates to declared:', ['Assets, liabilities, net worth, and business interests','Only an employee\'s favorite books','Private medical diagnoses only','A coworker\'s exam score'],0,'Section 8 identifies assets, liabilities, net worth, and business interests as disclosure subjects','the other choices are unrelated or protected personal information');
add(2,'A public official may accept a nominal foreign-government souvenir when it is:', ['Of nominal value and received as a souvenir or mark of courtesy','A secret payment for a pending permit','A demand for a luxury car','A condition for changing an audit'],0,'RA 6713 recognizes a nominal foreign-government souvenir as a limited exception while prohibiting gifts tied to favors','the other choices are valuable, secret, and connected to official action');
add(2,'The political-neutrality norm is most directly tested when an employee:', ['Provides the same service to supporters and opponents','Speeds up only a donor\'s application','Refuses service after seeing a campaign shirt','Uses a government seal for a party rally'],0,'Equal service regardless of party affiliation demonstrates political neutrality','the other choices create partisan discrimination or misuse office');
// Peace, human rights, and environment.
add(3,'The principle of universality of human rights means rights belong to:', ['All people without unjust discrimination','Only elected officials','Only citizens with property','Only people in wartime'],0,'Human rights attach to all persons and must not be denied through unjust discrimination','the other choices improperly limit rights by status or circumstance');
add(3,'A community peace process is strongest when parties:', ['Use dialogue, evidence, and nonviolent conflict resolution','Reward threats with public office','Suppress every disagreement','Spread unverified accusations'],0,'Dialogue and nonviolent resolution address conflict while respecting dignity and facts','the other choices intensify conflict or undermine rights');
add(3,'Habeas data is most closely associated with protection of:', ['Privacy and information about a person','A land title transfer','A customs tariff','A traffic citation'],0,'Habeas data provides a remedy concerning unlawful gathering, storage, or use of personal data affecting privacy','the other choices concern unrelated legal subjects');
add(3,'The writ of amparo is principally a protective remedy for threats to:', ['Life, liberty, and security','A restaurant license','A school\'s grading scale','A private trademark'],0,'The writ of amparo protects the rights to life, liberty, and security in qualifying threats or violations','the other choices do not identify the protected rights');
add(3,'A human-rights-based public program should begin by asking whether a policy:', ['Respects dignity, equality, participation, and accountability','Benefits only the most powerful group','Avoids all public explanation','Treats complaints as disloyalty'],0,'A rights-based approach centers dignity, equality, participation, and accountability','the other choices exclude affected people or reject accountability');
add(3,'Which action supports inclusive peace education?', ['Teaching mediation and respect for different identities','Calling every disagreement treason','Using humiliation as discipline','Blocking all community dialogue'],0,'Mediation and respect help learners manage differences without violence','the other choices normalize repression or exclusion');
add(4,'RA 9003 is principally known as the:', ['Ecological Solid Waste Management Act of 2000','Philippine Clean Air Act of 1999','Data Privacy Act','Civil Service Law'],0,'RA 9003 establishes the Philippine ecological solid-waste management program','the other choices name different subjects or statutes');
add(4,'Segregation at source means waste is separated:', ['Where it is generated','Only after being dumped in a river','After all waste is burned','Only at a foreign port'],0,'Segregation at source sorts waste at the household, office, or establishment where it arises','the other choices delay or defeat proper waste management');
add(4,'Composting is most suitable for processing:', ['Biodegradable organic material','Glass bottles only','Metal tools only','Electronic passwords'],0,'Composting biologically decomposes suitable organic waste into a useful soil amendment','the other choices are inorganic or not waste materials for composting');
add(4,'RA 8749 is commonly called the:', ['Philippine Clean Air Act of 1999','Ecological Solid Waste Management Act','Anti-Graft and Corrupt Practices Act','Cybercrime Prevention Act'],0,'RA 8749 establishes the Philippine comprehensive air-pollution control policy','the other choices concern different legal topics');
add(4,'An environmental impact assessment is useful because it:', ['Examines likely environmental effects before a covered project proceeds','Guarantees that every project has no impact','Replaces every local permit','Applies only to office stationery'],0,'Environmental assessment identifies likely impacts before decisions are made','the other choices exaggerate or misstate its function');
add(4,'The precautionary principle supports preventive action when:', ['A serious risk exists even though scientific certainty is incomplete','Harm is certain to be harmless','Pollution has already ended forever','Only a foreign regulator objects'],0,'Precaution allows reasonable prevention when potential serious harm is uncertain but plausible','the other choices reject or distort preventive environmental governance');
add(4,'A watershed is important because it:', ['Collects and channels water through a drainage area','Is a type of office filing cabinet','Stores only marine passwords','Prevents every earthquake'],0,'A watershed is a land area that drains water to a common outlet','the other choices describe unrelated objects or impossible effects');
add(4,'Which practice best reduces plastic leakage into waterways?', ['Reduce unnecessary plastic, segregate waste, and recover recyclables','Throw bags into a storm drain','Burn mixed plastic beside homes','Leave packaging in a vacant lot'],0,'Reduction, segregation, and recovery interrupt the path from discarded plastic to waterways','the other choices increase pollution and health risk');
add(4,'A protected area is primarily managed to conserve:', ['Biodiversity and ecological processes','Unrestricted dumping sites','Automatic subdivision expansion','Private advertising space'],0,'Protected-area management conserves biodiversity, habitats, and ecological processes','the other choices conflict with conservation purposes');
add(4,'The national agency most associated with environment and natural resources management is:', ['Department of Environment and Natural Resources','Bureau of Internal Revenue','Land Transportation Office','Philippine Statistics Authority'],0,'DENR is the national department principally responsible for environment and natural resources management','the other agencies focus on tax, transport, or statistics');
add(3,'A peace agreement should include a monitoring mechanism mainly to:', ['Check compliance and surface problems early','Hide violations from communities','Replace all local voices','Make the agreement impossible to review'],0,'Monitoring supplies evidence of compliance and creates an early route for correction','the other choices undermine transparency and implementation');
add(3,'The human-rights principle of non-refoulement is generally concerned with not sending a person to:', ['A place where they face serious persecution or harm','A neighboring town for a lawful hearing','A public library','A scheduled medical appointment'],0,'Non-refoulement protects against transfer to a place of serious persecution or comparable grave harm','the other choices do not describe the protection concern');
add(4,'A circular-economy approach aims to:', ['Keep materials useful through reuse, repair, and recycling','Use each product once and dump it','Increase extraction without recovery','Mix hazardous waste with food scraps'],0,'Circular systems preserve material value through reuse, repair, and recovery','the other choices create waste or increase environmental risk');
add(4,'Open burning of mixed household waste is unsafe mainly because it can:', ['Release harmful smoke and pollutants','Purify every nearby water source','Create drinking water automatically','Eliminate all greenhouse gases'],0,'Open burning can release harmful particulates and toxic pollutants','the other choices claim effects contrary to basic environmental science');
// English verbal ability.
add(5,'The word \'circumspect\' most nearly means:', ['Careful and watchful','Careless and rushed','Extremely noisy','Already forgotten'],0,'Circumspect describes a person who considers risks carefully before acting','the other choices are opposites or unrelated meanings');
add(5,'A person who is \'tenacious\' is likely to be:', ['Persistent','Easily discouraged','Indifferent to every task','Unable to remember a name'],0,'Tenacious means persistent and not easily giving up','the other choices describe lack of persistence or unrelated traits');
add(5,'The antonym of \'mitigate\' is:', ['Intensify','Reduce','Soften','Relieve'],0,'To mitigate is to lessen, so intensify is its opposite','the other choices are synonyms of mitigate');
add(5,"'Pragmatic' most nearly means:", ['Practical and results-oriented','Purely imaginary','Hostile to evidence','Unable to make a choice'],0,'Pragmatic decisions focus on workable results and real conditions','the other choices do not express practical judgment');
add(5,"'Lucid' writing is:", ['Clear and easy to understand','Deliberately confusing','Written without verbs','Always handwritten'],0,'Lucid means clear, coherent, and understandable','the other choices describe confusion or irrelevant form');
add(5,'The word \'abate\' most nearly means:', ['Become less intense','Become illegal','Multiply instantly','Move alphabetically'],0,'Abate means to lessen in force or intensity','the other choices do not express reduction');
add(5,'An \'impartial\' decision is one that is:', ['Fair and unbiased','Secretly favorable to a friend','Based on rumor','Made before hearing facts'],0,'Impartial means free from favoritism or bias','the other choices describe partiality or unfair procedure');
add(5,"'Concur' most nearly means:", ['Agree','Withdraw a file','Calculate a tax','Disagree violently'],0,'Concur means to agree or share an opinion','the other choices are unrelated or opposite');
add(5,'A \'viable\' proposal is:', ['Capable of succeeding in practice','Certain to fail','Already illegal','Impossible to explain'],0,'Viable means workable or capable of being carried out successfully','the other choices deny feasibility or introduce unrelated claims');
add(5,'The antonym of \'scarce\' is:', ['Abundant','Rare','Limited','Insufficient'],0,'Abundant means plentiful, the opposite of scarce','the other choices repeat the idea of shortage');
add(6,'The records were filed promptly, _____ the audit could begin on schedule.', ['so that','unless','although','whereas'],0,'So that expresses the purpose of filing promptly','the other conjunctions express a condition, contrast, or comparison rather than purpose');
add(6,'The supervisor remained calm _____ the queue became longer.', ['although','because of','in order to','therefore'],0,'Although introduces the contrast between calm behavior and a longer queue','the other choices do not correctly connect the contrasting clauses');
add(6,'The clerk checked the reference number _____ submitting the report.', ['before','despite','unless','whereas'],0,'Before correctly places checking earlier than submission','the other choices do not express the required time relationship');
add(6,'The agency revised the form _____ applicants reported repeated confusion.', ['because','unless','whereas','despite'],0,'Because gives the reason for revising the form','the other choices do not express the stated cause');
add(6,'The notice was written in plain language _____ every visitor could understand it.', ['so that','even though','instead of','whereas'],0,'So that states the intended result of using plain language','the other choices do not express purpose or result here');
add(6,'The officer acted _____ the written procedure, not by personal preference.', ['according to','because of','although','until'],0,'According to means in conformity with the written procedure','the other choices express cause, contrast, or time rather than conformity');
add(6,'The meeting was postponed _____ the key participants were unavailable.', ['because','unless','whereas','despite'],0,'Because gives the reason for postponement','the other choices do not provide the correct causal link');
add(6,'The team continued the inspection _____ the rain.', ['despite','because','so that','unless'],0,'Despite introduces a contrast between inspection and rain','the other choices do not fit a noun phrase showing an obstacle');
add(6,'The applicant submitted a copy _____ the original document.', ['instead of','because','although','whereas'],0,'Instead of correctly shows substitution of a copy for the original','the other choices do not express replacement');
add(6,'The request will be processed _____ all required fields are complete.', ['provided that','although','because of','whereas'],0,'Provided that introduces the condition for processing','the other choices do not express a condition');
add(7,'Which sentence contains an error in subject-verb agreement?', ['The list of names is on the desk.','The reports from each unit are ready.','The set of keys were returned.','The clerks review the forms.'],2,'The subject set is singular, so the verb should be was, not were','the other sentences correctly match their verbs to their subjects');
add(7,'Which sentence contains an incorrect pronoun case?', ['The supervisor spoke with Ana and me.','He and I prepared the index.','Between you and I, the file is incomplete.','They submitted their reports.'],2,'The preposition between requires the object pronoun me, so the phrase should be between you and me','the other sentences use pronouns in appropriate cases');
add(7,'Which sentence contains a dangling modifier?', ['After reading the memo, Carlo filed it.','While waiting for the bus, the clerk reviewed notes.','After the audit ended, the team issued a summary.','Walking through the hallway, the lights were unusually bright.'],3,'Walking describes a person, but the sentence makes the lights appear to be walking','the other sentences attach their introductory phrases to sensible actors');
add(7,'Which sentence uses a comma incorrectly?', ['The office opened at eight, and visitors entered.','After lunch, the team resumed work.','The clerk who arrived early, organized the files.','The report was concise, clear, and complete.'],2,'A restrictive who-clause should not be separated from its subject by that comma','the other sentences use commas for independent clauses, introductory phrases, or a series');
add(7,'Which sentence has an error in verb tense consistency?', ['The analyst reviewed the figures and corrected the table.','The clerk checks the form and records the date.','The team inspected the room and files a report yesterday.','The officer will call and will confirm the schedule.'],2,'The past-time marker yesterday requires filed, not present-tense files','the other sentences keep their verbs in compatible time frames');
add(7,'Which sentence uses an ambiguous pronoun?', ['When Mara called Liza, she was already outside.','Mara called Liza after lunch.','Liza signed the attendance sheet.','The supervisor called the office.'],0,'She could refer to either Mara or Liza, so the pronoun lacks a clear antecedent','the other choices name their subjects clearly');
add(8,'Which option is a complex sentence?', ['The clerk sorted the folders.','The clerk sorted the folders, and the aide labeled them.','Although the queue was long, the clerk remained patient.','Sort the folders now.'],2,'Although introduces a dependent clause joined to an independent clause','the other choices are simple, compound, or imperative rather than complex');
add(8,'Which option is a compound sentence?', ['The report is complete.','Because the report is complete.','The report is complete, and the supervisor signed it.','Complete report.'],2,'The sentence joins two independent clauses with and','the other choices contain one clause or a fragment');
add(8,'Which sentence has correct parallel structure?', ['The job requires filing, checking, and answering calls.','The job requires filing, checking, and to answer calls.','The job requires file, checking, and calls.','The job requires to file, checking, and answering.'],0,'The three gerunds filing, checking, and answering have the same grammatical form','the other choices mix gerunds, infinitives, nouns, and verbs');
add(8,'Which revision removes the run-on sentence from \'The form was incomplete the clerk returned it\'?', ['The form was incomplete, so the clerk returned it.','The form was incomplete the clerk returned it.','The form was incomplete, the clerk returned it.','The form incomplete returned clerk it.'],0,'A comma and coordinating conjunction correctly join the two independent clauses','the other choices retain a run-on, create a comma splice, or omit sentence structure');
add(8,'Which option is a sentence fragment?', ['The office closes at five.','When the office closes at five.','The office closed at five, and the guard left.','Close the office at five.'],1,'When introduces a dependent clause that lacks an independent clause','the other choices are complete statements or an imperative');
add(9,'Which sentence is the best topic sentence for a paragraph about faster permit processing?', ['Clear checklists can reduce avoidable permit delays.','The building has three windows.','Yesterday was humid.','Some forms are blue.'],0,'The first sentence states the paragraph\'s controlling idea about reducing delays','the other choices are narrow details or unrelated facts');
add(9,'Which order best organizes instructions for submitting a form?', ['Complete the fields, attach proof, review the entries, then submit.','Submit first, then decide which form is needed.','Archive the form before writing on it.','Choose a filing shelf before reading the instructions.'],0,'A process is clearest when actions follow the actual submission sequence','the other choices reverse or omit essential steps');
add(9,'A paragraph has one sentence about parking and four about document security. To improve unity, the writer should:', ['Remove or relocate the unrelated parking sentence','Add three more parking sentences','Delete the document-security details','Change every verb to past tense'],0,'Unity requires every sentence to support the paragraph\'s controlling idea','the other choices increase distraction or alter grammar without fixing relevance');
add(9,'Which transition best signals a contrast?', ['However','Similarly','Therefore','For example'],0,'However introduces a contrast between ideas','the other choices signal similarity, result, or illustration');
add(9,'Which transition best signals a result?', ['Therefore','Meanwhile','For instance','Likewise'],0,'Therefore introduces a conclusion or result','the other choices signal time, example, or similarity');
add(10,'A notice says, \'Visitors who submit complete forms before noon receive same-day screening.\' Who qualifies?', ['A visitor with a complete form submitted at 11:30 a.m.','A visitor with an incomplete form at 10:00 a.m.','A visitor with a complete form submitted at 1:00 p.m.','A person who never submits a form'],0,'The stated conditions are completeness and submission before noon','the other choices miss completeness, miss the deadline, or omit submission');
add(10,'A report says errors fell after peer review, but it does not compare other offices. The safest inference is:', ['Peer review may have contributed to the decline','Peer review alone caused every improvement','Errors will never return','Other offices cannot use peer review'],0,'The before-and-after association supports a cautious possibility, not proof of sole causation','the other choices claim certainty not established by the report');
add(10,'A paragraph states that online forms reduce encoding time but require reliable internet. Its balanced conclusion is:', ['Online forms offer efficiency but depend on connectivity','Online forms have no possible benefit','Internet access is irrelevant','Paper forms are always illegal'],0,'The conclusion preserves both the benefit and the stated limitation','the other choices ignore or reverse a material part of the passage');
add(10,'If a memo says the pilot served 30 of 40 applicants, what fraction were served?', ['Three-fourths','One-fourth','Two-fifths','Four-thirds'],0,'Thirty divided by forty simplifies to three-fourths','the other fractions do not equal the stated served-to-total ratio');
add(10,'A policy says records are retained for five years unless a litigation hold applies. What is the exception?', ['A litigation hold','A quiet office','A new printer','A staff meeting'],0,'The phrase unless identifies the litigation hold as the exception','the other choices are not listed as exceptions in the policy');
// Filipino language and grammar, original practice.
add(6,"Piliin ang wastong gamit: '_____ dumating ang pinuno, sinimulan ang pulong.'",['Nang','Ng','Nang sa','Kung'],0,'Ginagamit ang nang bilang pangatnig na nag-uugnay sa kilos at oras','ang ng ay pananda ng pagmamay-ari o layon, at hindi angkop ang iba sa pangungusap', 'Filipino');
add(6,'Alin ang wastong pangungusap?',['Mabilis na tumakbo ang bata.','Mabilis nang tumakbo ang bata na.','Mabilis ng tumakbo ang bata.','Mabilis na ang tumakbo bata.'],0,'Wasto ang ayos na pang-abay na sinusundan ng na at pandiwa','ang ibang pagpipilian ay may maling gamit ng pang-angkop o maling ayos');
add(6,"Piliin ang wastong salita: 'Mabuting _____ ang panukala bago ito pagtibayin.'",['subukin','subukan','sinubok','pagsubok'],1,'Ang subukan ay nangangahulugang tangkaing gawin o siyasatin ang isang bagay','ang subukin ay karaniwang may ibang gamit, habang ang dalawang anyo ay hindi angkop sa puwang');
add(7,'Alin ang wastong baybay?',['pinagkakakitaan','pinagkakakitaan','pinagkakitaan','pinagkakitaan'],0,'Ang wastong anyo ng salita ay pinagkakakitaan','ang ibang pagpipilian ay kaparehong anyo lamang sa payak na anyo at hindi dapat gamitin bilang distractor');
add(7,"Alin ang wastong gamit ng 'rin' at 'din'?",['Mabuti rin ang mungkahi niya.','Mabuti din ang mungkahi niya kapag patinig ang hulihan.','Mabuti rin ang mungkahi niya ay.','Mabuti din rin ang mungkahi niya.'],0,'Karaniwang ginagamit ang rin kapag patinig ang huling tunog ng naunang salita, gaya ng mabuti','ang ibang pangungusap ay may maling tuntunin o dobleng pang-abay');
add(8,'Alin ang nasa karaniwang ayos?',['Nagsumite ng ulat ang kawani.','Ng ulat nagsumite ang kawani.','Ang kawani ng ulat nagsumite.','Nagsumite ang ulat ng kawani.'],0,'Sa karaniwang ayos, nauuna ang panaguri at sumusunod ang simuno','ang ibang ayos ay baligtad, malabo, o nagbabago ng kahulugan');
add(8,'Alin ang pangungusap na nasa di-karaniwang ayos?',['Ang kawani ay nagsumite ng ulat.','Nagsumite ng ulat ang kawani.','Nagsumite ang kawani ng ulat.','Ulat ang nagsumite ng kawani.'],0,'Sa di-karaniwang ayos, nauuna ang simuno at karaniwang ginagamit ang ay','ang ibang pagpipilian ay karaniwang ayos o mali ang ugnayan ng mga salita');
add(10,"Basahin: 'Maagang nagbukas ang tanggapan upang mapaglingkuran ang mga aplikante.' Ano ang dahilan ng maagang pagbubukas?",['Mapaglingkuran ang mga aplikante','Magsara nang mas maaga','Magdaos ng paligsahan','Magpalit ng gusali'],0,'Ang pariralang upang mapaglingkuran ang mga aplikante ay nagsasaad ng layunin','ang ibang sagot ay hindi binanggit o salungat sa pangungusap');
// Analytical ability.
add(11,'Key is to lock as password is to:', ['Account','Chair','Envelope','Window'],0,'A key grants access to a lock, while a password grants access to an account','the other choices are not the normal access target of a password');
add(11,'Blueprint is to building as recipe is to:', ['Dish','Broom','Invoice','Passport'],0,'A blueprint guides construction of a building, while a recipe guides preparation of a dish','the other choices are not products prepared from the respective guide');
add(11,'Seed is to plant as draft is to:', ['Document','Stapler','Desk','Calendar'],0,'A seed develops into a plant, while a draft develops into a document','the other choices are tools or objects rather than the resulting work');
add(11,'Thermometer is to temperature as clock is to:', ['Time','Distance','Weight','Volume'],0,'A thermometer measures temperature, while a clock measures time','the other quantities require different measuring instruments');
add(11,'Judge is to verdict as editor is to:', ['Revision','Medicine','Weather','Fuel'],0,'A judge produces a verdict, while an editor produces or approves a revision','the other choices are unrelated outputs');
add(12,'If ▲ means plus and ■ means minus, what is 9 ▲ 4 ■ 3?', ['10','12','16','6'],0,'Replace the symbols and compute 9 plus 4 minus 3, which equals 10','the other choices misread one symbol or perform the arithmetic incorrectly');
add(12,'A code changes each letter to the next alphabet letter. What is PLAN under the rule?', ['QMBO','OKZM','QKBO','PMBO'],0,'Advance P to Q, L to M, A to B, and N to O to obtain QMBO','the other choices move one or more letters by the wrong amount');
add(12,'A sequence follows add 3, then add 5, then add 7, repeating. What comes after 10, 13, 18, 25?', ['28','30','32','34'],0,'The next increment is 3, so 25 plus 3 equals 28','the other choices use a different increment or skip the repeating pattern');
add(12,'If all R are S and no S are T, which must be true?', ['No R are T','All T are R','Some R are T','All S are R'],0,'R is contained in S, and S excludes T, so R also excludes T','the other choices reverse or overstate the given relationships');
add(12,'Four symbols rotate one place left: A, B, C, D becomes B, C, D, A. What is the next rotation?', ['C, D, A, B','D, A, B, C','A, C, B, D','B, A, D, C'],0,'Rotating the current sequence left again moves B to the end after C and D, giving C, D, A, B','the other sequences rotate in another direction or change the order');
add(13,'Claim: \'Install a queue display because visitors cannot tell when they will be called.\' The needed assumption is:', ['A display can give visitors useful queue information','Visitors never wait','The office will abolish service numbers','The display must be outdoors'],0,'The recommendation depends on a display being capable of informing waiting visitors','the other choices are unnecessary or contradict the proposed solution');
add(13,'All verified forms carry a validation stamp. Form K has no stamp. What follows?', ['K is not shown to be verified','K is definitely forged','Every form is unverified','K must be approved'],0,'The rule supports only that verification is not established when the required stamp is absent','the other choices assert fraud, universal failure, or approval without evidence');
add(13,'A manager says, \'Training should be repeated because errors rose after six months.\' Which assumption supports the proposal?', ['Refresher training could reduce the errors','Errors are always caused by weather','No employee can learn procedures','The training room must be demolished'],0,'The proposal assumes refresher training could address the later error increase','the other choices do not support a training-based remedy');
add(13,'Some archived files are confidential. File Z is archived. Which conclusion is valid?', ['Z may be confidential, but confidentiality is not guaranteed','Z is certainly public','No archived file is confidential','Z is destroyed'],0,'The statement allows overlap but does not say every archived file is confidential','the other choices turn a possibility into certainty or deny the given possibility');
add(14,'A service desk handled 36 cases Monday and 45 Tuesday. What was the percentage increase from Monday to Tuesday?', ['25%','20%','9%','80%'],0,'The increase is 9, and 9 divided by 36 equals 25 percent','the other choices use the wrong base or confuse the difference with a percentage');
add(14,'A budget of 120,000 assigns 30 percent to training and 10 percent to supplies. What amount remains?', ['72,000','48,000','84,000','60,000'],0,'The assigned share is 40 percent, so the remaining 60 percent of 120,000 is 72,000','the other choices use the assigned amount or an incorrect percentage');
add(14,'A team completes 18 of 24 reviews. What fraction remains incomplete?', ['One-fourth','Three-fourths','One-half','One-eighth'],0,'Six reviews remain; 6 divided by 24 simplifies to one-fourth','the other choices do not represent the incomplete portion');
add(14,'A chart lists 12, 18, 15, and 15 complaints over four weeks. What is the median?', ['15','14','16','18'],0,'After ordering the values, the two middle values are 15 and 15, so the median is 15','the other choices are not the middle value of the ordered data');
add(14,'A unit\'s output rises from 80 to 100 items. The increase as a fraction of the original is:', ['One-fourth','One-fifth','One-half','Four-fifths'],0,'The increase is 20 and 20 divided by 80 equals one-fourth','the other choices use a different denominator or ratio');
// Numerical ability.
add(15,'Compute 84 divided by 7 plus 6 multiplied by 3.', ['30','36','42','48'],0,'Division and multiplication come first: 84 divided by 7 is 12 and 6 multiplied by 3 is 18, so the sum is 30','the other choices ignore order of operations or miscalculate a component');
add(15,'What is 18 percent of 250?', ['45','36','40','50'],0,'Ten percent of 250 is 25 and eight percent is 20, so 18 percent is 45','the other choices use the wrong percentage');
add(15,'A clerk uses 7/8 of 64 labels. How many labels are used?', ['56','48','54','60'],0,'Divide 64 by 8 to get 8, then multiply by 7 to get 56','the other choices use a different fraction of 64');
add(15,'Evaluate 6.4 minus 2.75.', ['3.65','3.75','4.35','2.35'],0,'Align decimal places and subtract: 6.40 minus 2.75 equals 3.65','the other choices contain subtraction or decimal-place errors');
add(15,'A 1,500-peso allowance is reduced by 12 percent. What is the new amount?', ['1,320','1,288','1,350','1,680'],0,'Twelve percent of 1,500 is 180, and 1,500 minus 180 equals 1,320','the other choices subtract the wrong amount or increase the allowance');
add(16,'Find the next term: 5, 9, 17, 33, __.', ['65','49','66','72'],0,'Each term is doubled and then reduced by 1: 33 multiplied by 2 minus 1 equals 65','the other choices do not continue the same rule');
add(16,'Find the next term: 2, 6, 12, 20, __.', ['30','28','32','36'],0,'The differences are 4, 6, 8, so the next difference is 10 and 20 plus 10 equals 30','the other choices use the wrong next difference');
add(16,'Find the missing term: 96, 48, 24, 12, __.', ['6','4','8','3'],0,'Each term is divided by 2, so 12 divided by 2 equals 6','the other choices do not continue repeated halving');
add(16,'Which number completes 3, 6, 12, 24, __, 96?', ['48','36','60','72'],0,'Each term doubles, so 24 multiplied by 2 equals 48','the other choices do not preserve the doubling pattern');
add(17,'Four clerks process 160 forms in two hours at equal rates. How many forms does one clerk process per hour?', ['20','40','80','160'],0,'One clerk handles 160 divided by 4 divided by 2, which is 20 forms per hour','the other choices omit one of the divisions or use the total rate');
add(17,'A 15 percent discount is applied to a 2,400-peso fee. What is the discounted fee?', ['2,040','2,160','2,085','2,760'],0,'Fifteen percent of 2,400 is 360, and subtracting it gives 2,040','the other choices use ten percent, a wrong discount, or an increase');
add(17,'A vehicle travels 210 kilometers in 3.5 hours. At the same speed, how far in 2 hours?', ['120 km','105 km','140 km','150 km'],0,'The speed is 210 divided by 3.5, or 60 kilometers per hour; two hours gives 120 kilometers','the other choices use an incorrect speed or time');
add(17,'A tank is 3/5 full at 72 liters. What is its full capacity?', ['120 liters','108 liters','90 liters','135 liters'],0,'If three-fifths is 72, one-fifth is 24 and five-fifths is 120 liters','the other choices scale the fraction incorrectly');
add(17,'A project has 18 tasks. A team completes 2/3 in week one and 4 more in week two. How many remain?', ['2','4','6','8'],0,'Two-thirds of 18 is 12; after four more, 16 are complete and 2 remain','the other choices confuse completed tasks with remaining tasks');
// Clerical filing and spelling.
add(18,'Which surname sequence is in correct alphabetic order?', ['Alonzo, Alvarado, Amador, Aquino','Alvarado, Alonzo, Aquino, Amador','Aquino, Amador, Alonzo, Alvarado','Amador, Aquino, Alvarado, Alonzo'],0,'Compare letters from left to right: Alonzo precedes Alvarado, then Amador, then Aquino','the other sequences place a later letter before an earlier one');
add(18,'Which file should come immediately before \'Santos, Maria\'?', ['Santos, Luis','Santos, Pedro','Santiago, Ana','Salazar, Ana'],0,'Within the Santos group, Luis precedes Maria and Pedro follows Maria','the other choices are after Maria or belong to an earlier surname group');
add(18,'When filing \'De Leon, Carla\' and \'Delos Reyes, Ana\', which comes first under letter-by-letter filing?', ['De Leon, Carla','Delos Reyes, Ana','They are always tied','The later-dated document'],0,'The space-free comparison begins De L before Del, so De Leon comes first','the other choices ignore the alphabetic comparison or introduce an irrelevant date');
add(18,'Which numeric sequence is ascending?', ['007, 018, 102, 120','007, 102, 018, 120','018, 007, 120, 102','120, 102, 018, 007'],0,'Numeric filing compares the values, giving 7, 18, 102, then 120','the other choices place a larger number before a smaller one');
add(18,'A folder marked 2027-014 should be filed immediately before:', ['2027-015','2026-099','2027-004','2028-001'],0,'Within the same year, 014 is immediately before 015','the other choices are earlier, not adjacent, or in a later year');
add(18,'Which label best identifies approved travel claims for the second quarter of 2027?', ['Approved Travel Claims, Q2 2027','Travel','Claims maybe','Second'],0,'A complete label states subject, status, and period: Approved Travel Claims, Q2 2027','the other choices omit information needed for reliable retrieval');
add(18,'An out-guide is placed when a folder is removed to record:', ['The folder and the borrower or destination','A random replacement subject','The clerk\'s lunch time','A new unrelated account number'],0,'An out-guide identifies what was removed and where it went','the other choices do not support tracking and refiling');
add(18,'In terminal-digit filing of 41-27-83, which group is read first?', ['83','27','41','The groups are ignored'],0,'Terminal-digit filing uses the rightmost group as the primary key, so 83 is read first','the other choices start with a nonprimary group or ignore the system');
add(18,'A cross-reference in a subject file should:', ['Direct the user from an alternate subject to the primary file','Create an untracked duplicate everywhere','Replace the original record','Hide the file number'],0,'A cross-reference preserves one primary record while pointing from another likely access point','the other choices create duplication, loss, or concealment');
add(18,'Which date order is chronological from earliest to latest?', ['08 February 2027; 19 February 2027; 03 March 2027; 12 April 2027','12 April 2027; 03 March 2027; 19 February 2027; 08 February 2027','19 February 2027; 08 February 2027; 12 April 2027; 03 March 2027','03 March 2027; 08 February 2027; 19 February 2027; 12 April 2027'],0,'Chronological order compares year, month, and day from earliest to latest','the other choices reverse or scramble the calendar order');
add(19,'Which spelling is correct for the office word?', ['Accommodate','Acommodate','Accomodate','Accommadate'],0,'Accommodate has double c and double m','the other choices omit or replace one of those letters');
add(19,'Which spelling is correct for the selected term?', ['Occurrence','Occurence','Occurrance','Ocurrence'],0,'Occurrence has double c, double r, and the ending -ence','the other choices omit or change required letters');
add(19,'Which spelling is correct in this sentence?', ['Separate','Seperate','Seperrate','Separete'],0,'Separate follows the spelling sep-a-rate','the other choices change the middle vowels or add a consonant');
add(19,'Which spelling is correct for the vocabulary item?', ['Privilege','Privelege','Priviledge','Privilage'],0,'Privilege contains no d and uses the sequence -ilege','the other choices insert, omit, or change letters');
add(19,'Which spelling is correct for the record?', ['Maintenance','Maintainance','Maintenence','Maintanance'],0,'Maintenance uses the sequence mainten-ance','the other choices alter the vowel pattern');
add(19,'Which spelling is correct in the following choice?', ['Questionnaire','Questionaire','Questionnare','Questioneer'],0,'Questionnaire has double n and the ending -naire','the other choices omit or alter letters in the ending');
add(19,'Which spelling is correct for this word?', ['Conscientious','Consciencious','Consientious','Conscientous'],0,'Conscientious contains the sequence sci-ent-i-ous','the other choices omit or rearrange letters');
add(19,'Which spelling is correct, item 8?', ['Embarrass','Embarass','Embarrase','Embarres'],0,'Embarrass has double r and double s','the other choices omit or change one of the doubled consonants');
add(19,'Which spelling is correct, item 9?', ['Definitely','Definately','Definitly','Definetely'],0,'Definitely contains the sequence finite and ends in -ely','the other choices change or omit letters in the middle');
add(19,'Which spelling is correct, item 10?', ['Miscellaneous','Miscelaneous','Miscellanous','Misceallaneous'],0,'Miscellaneous contains -cellan- and ends in -eous','the other choices omit or rearrange letters');


// Additional original items to complete the requested 200-item local batch.
add(1,'Which constitutional protection most directly limits a bill of attainder?', ['Government may not legislatively declare a person guilty and punish them','Every bill must concern a budget','Courts may never review statutes','A local ordinance becomes a treaty'],0,'A bill of attainder is a legislative act that declares a person or group guilty and imposes punishment without a judicial trial','the other choices describe unrelated legislative or international matters');
add(1,'A public office denies a permit solely because an applicant criticized the mayor. Which principle is most implicated?', ['Freedom of expression and equal protection','The power to coin money','The rule on natural-born citizenship','The authority to audit accounts'],0,'Punishing lawful criticism implicates expression and arbitrary unequal treatment','the other choices do not address retaliation for speech');
add(1,'Which branch has the power to appropriate public funds?', ['Congress','The Supreme Court alone','A private bank','A barangay sports club'],0,'Appropriation is a legislative function exercised by Congress through law','the other choices do not enact the national budget');
add(1,'The constitutional requirement of just compensation applies when government:', ['Takes private property for public use','Publishes a weather bulletin','Conducts a public hearing','Counts election ballots'],0,'Just compensation accompanies a public-use taking under eminent domain','the other choices do not involve taking private property');
add(1,'Which statement best reflects freedom of religion?', ['The state may not establish a religion or prohibit its free exercise, subject to lawful limits','Only one religion may receive constitutional protection','Religious belief removes every criminal law','Public officials may deny service based on faith'],0,'The Constitution protects free exercise and bars government establishment of religion','the other choices impose preference, immunity, or discrimination');
add(2,'A public employee uses an official vehicle for a private vacation. Which RA 6713 norm is most directly violated?', ['Efficient, honest, and economical use of government resources','Natural-born citizenship','The right to suffrage','The rule on court jurisdiction'],0,'RA 6713 requires government resources to be used efficiently, effectively, honestly, and economically for public purposes','the other choices concern unrelated constitutional subjects');
add(2,'Which conduct best demonstrates responsiveness to the public?', ['Explaining procedures clearly and attending to a transaction promptly','Sending an applicant from desk to desk without guidance','Using jargon to discourage questions','Ignoring a request until the deadline passes'],0,'Responsiveness requires prompt, courteous, adequate service and understandable information','the other choices create delay, confusion, or neglect');
add(2,'A public employee discovers a mistake in a submitted SALN. The ethical course is to:', ['Correct and resubmit it through the required review process','Hide the mistake until retirement','Delete the office copy','Ask a friend to sign a blank replacement'],0,'Accurate disclosure and correction through the prescribed process protect the integrity of the SALN','the other choices conceal or falsify a public record');
add(4,'Which waste-management choice follows the waste hierarchy most closely?', ['Prevent waste first, then reuse and recover materials before final disposal','Mix all waste and burn it in an open area','Dump reusable materials with residual waste','Send every item directly to a landfill'],0,'Prevention, reuse, and recovery preserve resources before disposal is considered','the other choices increase waste and pollution');
add(4,'Mangroves help coastal communities mainly by:', ['Providing habitat and reducing wave and erosion impacts','Increasing plastic leakage','Removing all rainfall','Replacing every inland forest'],0,'Mangroves provide habitat and can reduce coastal erosion and wave energy','the other choices claim impossible or harmful effects');
add(4,'Which office practice reduces paper consumption without sacrificing records control?', ['Use an approved digital workflow with backups and retention rules','Delete files without authorization','Print every draft several times','Store sensitive records on an unprotected public drive'],0,'A controlled digital workflow can reduce paper while preserving retention, access, and security','the other choices risk loss, waste, or unauthorized disclosure');
add(5,"The word 'meticulous' most nearly means:",['Very careful and exact','Carelessly improvised','Unable to notice detail','Unrelated to quality'],0,'Meticulous describes work done with great care and attention to detail','the other choices express carelessness or unrelated ideas');
add(5,"The antonym of 'concise' is:",['Wordy','Brief','Compact','Succinct'],0,'Wordy is the opposite of concise because it uses more words than necessary','the other choices are synonyms of concise');
add(6,'The committee adopted the proposal _____ the legal review was complete.', ['after','unless','despite','whereas'],0,'After correctly places adoption later than completion of legal review','the other choices do not express the required sequence');
add(7,'Which sentence is grammatically correct?', ['Neither the memo nor the attachments are missing.','Neither the memo nor the attachments is missing.','Neither the memo nor the attachments be missing.','Neither memo nor attachments was missing are.'],0,'With neither-nor, the verb agrees with the nearer plural subject attachments, so are is correct','the other choices use incorrect agreement or sentence structure');
add(8,"Which option correctly combines the ideas 'The file was old' and 'It remained legible'?",['Although the file was old, it remained legible.','The file was old it remained legible.','The file was old, it remained legible.','Although the file was old. It remained legible.'],0,'Although creates a dependent contrast clause joined to the independent clause','the other choices are a run-on, comma splice, or fragment');
add(9,'Which sentence best concludes a paragraph about secure password practices?', ['Strong password habits reduce avoidable account risks.','The office has a green door.','Some keyboards are wireless.','Yesterday had light traffic.'],0,'The first sentence returns to the paragraph topic and gives a concise closing idea','the other choices introduce unrelated details');
add(10,"A memo says, 'Only complete applications received by Friday will enter Monday's review batch.' Which application qualifies?",['Complete and received Thursday','Incomplete and received Thursday','Complete and received Saturday','Complete but never received'],0,'The application must be complete and received before the Friday cutoff','the other choices fail one of the stated conditions');
add(11,'Gloves are to hands as shoes are to:', ['Feet','Roads','Books','Windows'],0,'Gloves cover and protect hands, while shoes cover and protect feet','the other choices are not the body part protected by shoes');
add(12,'If @ means divide and # means add, what is 18 @ 3 # 4?', ['10','14','22','30'],0,'Replace the symbols and follow precedence: 18 divided by 3 plus 4 equals 10','the other choices mishandle division or addition');
add(13,'A report recommends a second service window because the first has long lines. The key assumption is:', ['A second window can serve some clients without creating greater delay elsewhere','All clients dislike service windows','The office has no staff at all','The first window should be closed permanently'],0,'The recommendation depends on extra capacity being able to reduce the queue','the other choices do not support or are not required by the recommendation');
add(14,'A team receives 50 applications, approves 32, and rejects 8. How many remain pending?', ['10','18','24','40'],0,'Pending applications equal 50 minus 32 approved minus 8 rejected, or 10','the other choices subtract the wrong categories');
add(15,'Compute 7 multiplied by 8 minus 15.', ['41','31','56','71'],0,'Multiply first: 7 times 8 is 56, then subtract 15 to get 41','the other choices omit or reverse the required operation');
add(16,'Find the next term: 100, 90, 75, 55, __.', ['30','35','40','25'],0,'The differences are minus 10, minus 15, minus 20, so subtract 25 from 55 to get 30','the other choices use the wrong next difference');
add(17,'A printer produces 240 pages in 6 minutes. At the same rate, how many pages in 9 minutes?', ['360','300','400','420'],0,'The rate is 240 divided by 6, or 40 pages per minute; 9 minutes gives 360','the other choices use an incorrect rate or duration');
add(18,'Which name comes first in a strict alphabetic file?', ['Garcia, Liza','Garcia, Mila','Gomez, Ana','Gonzales, Ben'],0,'Compare the surname first; Garcia precedes Gomez and Gonzales, and Liza precedes Mila','the other choices come later by surname or given name');
add(18,'A file labeled 03-118 should be placed before:', ['03-119','03-017','02-999','01-500'],0,'Within the same series, 118 is immediately before 119','the other choices are earlier numbers or different series');
add(18,'Which record description is most retrievable?', ['Personnel Leave Requests, Approved, January 2027','Papers','Important stuff','Blue folder'],0,'A useful description identifies subject, status, and period','the other choices are vague and do not support reliable retrieval');
add(19,'Which spelling is correct for the first term?', ['Entrepreneur','Enterpreneur','Entreprenuer','Entrepenur'],0,'Entrepreneur uses the sequence entre-pren-eur','the other choices omit or rearrange letters');
add(19,'Which spelling is correct for the second term?', ['Occurrence','Occurence','Ocurrence','Occurance'],0,'Occurrence has double c, double r, and the ending -ence','the other choices omit or change required letters');
add(19,'Which spelling is correct for the third term?', ['Receive','Recieve','Receeve','Receve'],0,'Receive follows the common i-before-e pattern after c','the other choices reverse or omit letters');


add(3,'A mediator should keep a peace dialogue credible by:', ['Applying agreed ground rules to every participant','Allowing threats from the strongest party','Publishing private testimony without consent','Ending discussion after one accusation'],0,'Consistent ground rules protect participation and trust in a dialogue','the other choices reward coercion, breach privacy, or end a process unfairly');
add(19,'Which spelling is correct for the calendar term?', ['Calendar','Calender','Calandar','Callendar'],0,'Calendar is the standard spelling for a schedule of dates','the other choices change the vowel pattern or add an extra consonant');
if (Q.length !== 200) throw new Error(`expected 200 items, got ${Q.length}`);
const norm = Q.map(q => q.stem.toLowerCase().replace(/\s+/g,' ').trim());
if (new Set(norm).size !== norm.length) throw new Error('duplicate stem in batch');
function esc(s){ return String(s).replace(/\x27/g, "\x27\x27"); }
const lines = ['-- Hiraya CSE-Pack: 200 original local-study items; not official CSC questions','-- Exact active-stem protection; generated '+new Date().toISOString(),'BEGIN;'];
for (const q of Q) {
  lines.push(`INSERT INTO questions (subcategory_id, language, stem, options, correct_option, explanation, status, created_by, created_at, updated_at) SELECT ${q.sub}, '${esc(q.lang)}', '${esc(q.stem)}', '${esc(JSON.stringify(q.options))}'::jsonb, ${q.correct}, '${esc(q.explanation)}', 'active', ${CREATED_BY}, NOW(), NOW() WHERE NOT EXISTS (SELECT 1 FROM questions WHERE status='active' AND lower(btrim(stem))=lower(btrim('${esc(q.stem)}')));`);
}
lines.push('COMMIT;','-- generated_items='+Q.length);
const out=path.join(__dirname,'seed_cse_pack_200_2026-10-03.sql'); fs.writeFileSync(out,lines.join('\n')+'\n','utf8'); console.log('TOTAL_QUESTIONS',Q.length,'OUT',out);



